draw:
ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';

var Rg = 8.31, n = 1, Cv = 1.5 * Rg, gam = 5 / 3;
var V0 = 0.02, T0 = p.T0, P0 = n * Rg * T0 / V0;
var mode = Math.round(p.proc);
var rEnd = (mode === 4) ? 1 : p.ratio;

// animate the volume back and forth along the process
var ph = 0.5 - 0.5 * Math.cos(t * 1.1);
var r = 1 + ph * (rEnd - 1);
var V = V0 * r;

function stateAt(rr) {
  var Vv = V0 * rr, Pp, Tt;
  if (mode === 1) { Pp = P0; Tt = T0 * rr; }
  else if (mode === 2) { Tt = T0; Pp = n * Rg * Tt / Vv; }
  else if (mode === 3) { Pp = P0 * Math.pow(rr, -gam); Tt = T0 * Math.pow(rr, 1 - gam); }
  else { Vv = V0; Pp = P0 * (1 + ph * 0.8); Tt = Pp * V0 / (n * Rg); }
  return [Vv, Pp, Tt];
}
var st = stateAt(r);
var Vc = st[0], Pc = st[1], Tc = st[2];

// work done by the gas from the start up to the current state
var Wk;
if (mode === 1) { Wk = P0 * (Vc - V0); }
else if (mode === 2) { Wk = n * Rg * T0 * Math.log(Vc / V0); }
else if (mode === 3) { Wk = n * Cv * (T0 - Tc); }
else { Wk = 0; }
var dU = n * Cv * (Tc - T0);
var Qh = dU + Wk;

// ---- left panel: the cylinder ----
var cx = W * 0.06, cw = W * 0.34, cy = H * 0.18, chh = H * 0.46;
var maxR = 4;
var fill = cw * (Vc / (V0 * maxR));
ctx.fillStyle = C.faint;
ctx.fillRect(cx, cy, fill, chh);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.strokeRect(cx, cy, cw, chh);
ctx.fillStyle = C.figure;
ctx.fillRect(cx + fill, cy, 7, chh);
ctx.fillStyle = C.ink;
ctx.fillText('gas', cx + Math.max(fill / 2, 16), cy + chh / 2);
ctx.fillText('piston', cx + fill + 26, cy - 12);
ctx.textAlign = 'left';
ctx.fillText('T = ' + Tc.toFixed(0) + ' K', cx, cy + chh + 18);
ctx.fillText('P = ' + (Pc / 1000).toFixed(0) + ' kPa', cx, cy + chh + 36);
ctx.fillText('V = ' + Vc.toFixed(4) + ' m3', cx, cy + chh + 54);
ctx.textAlign = 'center';

// ---- right panel: the P-V curve ----
var L = W * 0.52, R2 = W * 0.95, TOP = H * 0.12, BOT = H * 0.74;
var Vhi = V0 * 4.3, Phi = Math.max(P0 * 4.3, 1);
function X(v) { return L + v / Vhi * (R2 - L); }
function Y(P) { return BOT - P / Phi * (BOT - TOP); }
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(L, TOP - 4); ctx.lineTo(L, BOT); ctx.lineTo(R2, BOT);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText('V', (L + R2) / 2, BOT + 16);
ctx.save(); ctx.translate(L - 14, (TOP + BOT) / 2); ctx.rotate(-Math.PI / 2); ctx.fillText('P', 0, 0); ctx.restore();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
var steps = 50;
for (var i = 0; i <= steps; i++) {
  var rr = 1 + (i / steps) * (rEnd - 1);
  var s2 = stateAt(rr);
  if (i === 0) ctx.moveTo(X(s2[0]), Y(s2[1])); else ctx.lineTo(X(s2[0]), Y(s2[1]));
}
if (mode === 4) { ctx.moveTo(X(V0), Y(P0)); ctx.lineTo(X(V0), Y(P0 * 1.8)); }
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(Vc), Y(Pc), 5, 0, 6.2832); ctx.fill();

var names = ['isobaric: P fixed', 'isothermal: T fixed', 'adiabatic: Q = 0', 'isochoric: V fixed'];
ctx.fillStyle = C.ink;
ctx.fillText(names[mode - 1], (L + R2) / 2, H * 0.92);

out.note = names[mode - 1] + '   W = ' + Wk.toFixed(0) + ' J,  dU = ' + dU.toFixed(0) + ' J,  Q = ' + Qh.toFixed(0) + ' J';
